// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title PDFGenerationOracle
 * @notice Manages signed requests for off-chain PDF generation behind a reverse proxy.
 *         The reverse proxy forwards signed payloads; this contract validates and tracks them.
 */
contract PDFGenerationOracle {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct GenerationRequest {
        address requester;
        bytes32 documentHash;
        uint256 timestamp;
        uint256 nonce;
        string templateId;
    }

    address public immutable trustedSigner;
    address public immutable proxyRelayer;

    // Tracks consumed nonces per requester
    mapping(address => mapping(uint256 => bool)) private _consumedNonces;

    // Tracks generation requests
    mapping(bytes32 => bool) public processedRequests;

    // Chain-specific domain separator
    bytes32 public immutable DOMAIN_SEPARATOR;

    bytes32 private constant REQUEST_TYPEHASH = keccak256(
        "GenerationRequest(address requester,bytes32 documentHash,uint256 timestamp,uint256 nonce,string templateId)"
    );

    event PDFGenerationQueued(bytes32 indexed requestId, address indexed requester, string templateId);
    event NonceConsumed(address indexed requester, uint256 nonce);

    error InvalidSignature();
    error RequestAlreadyProcessed();
    error NonceAlreadyUsed();
    error RequestExpired();
    error UnauthorizedRelayer();

    constructor(address _trustedSigner, address _proxyRelayer) {
        trustedSigner = _trustedSigner;
        proxyRelayer = _proxyRelayer;

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("PDFGenerationOracle")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    /**
     * @notice Submit a signed PDF generation request via the reverse proxy
     * @param request The generation request parameters
     * @param signature The EIP-712 signature from the trusted signer
     */
    function submitGenerationRequest(
        GenerationRequest calldata request,
        bytes calldata signature
    ) external returns (bytes32 requestId) {
        // Only the proxy relayer can submit
        if (msg.sender != proxyRelayer) revert UnauthorizedRelayer();

        // Check timestamp validity (5 minute window)
        if (block.timestamp > request.timestamp + 300) revert RequestExpired();

        // Compute request ID from full signature digest for uniqueness
        requestId = _computeRequestId(request);

        // Check if already processed
        if (processedRequests[requestId]) revert RequestAlreadyProcessed();

        // Verify signature
        bytes32 structHash = _hashRequest(request);
        bytes32 digest = _toTypedDataHash(structHash);

        address recovered = digest.recover(signature);
        if (recovered != trustedSigner) revert InvalidSignature();

        // Mark as processed
        processedRequests[requestId] = true;

        // Validate and consume nonce
        _validateAndConsumeNonce(request.requester, request.nonce);

        emit PDFGenerationQueued(requestId, request.requester, request.templateId);
        emit NonceConsumed(request.requester, request.nonce);

        return requestId;
    }

    /**
     * @notice Batch submit multiple generation requests
     * @dev Used when the proxy batches multiple user requests
     */
    function batchSubmitRequests(
        GenerationRequest[] calldata requests,
        bytes[] calldata signatures
    ) external returns (bytes32[] memory requestIds) {
        if (msg.sender != proxyRelayer) revert UnauthorizedRelayer();

        requestIds = new bytes32[](requests.length);

        for (uint256 i = 0; i < requests.length; i++) {
            // Check timestamp validity
            if (block.timestamp > requests[i].timestamp + 300) revert RequestExpired();

            bytes32 requestId = _computeRequestId(requests[i]);

            if (processedRequests[requestId]) revert RequestAlreadyProcessed();

            // Verify signature
            bytes32 structHash = _hashRequest(requests[i]);
            bytes32 digest = _toTypedDataHash(structHash);

            address recovered = digest.recover(signatures[i]);
            if (recovered != trustedSigner) revert InvalidSignature();

            // Mark processed AFTER all validations
            processedRequests[requestId] = true;

            // Consume nonce
            _validateAndConsumeNonce(requests[i].requester, requests[i].nonce);

            requestIds[i] = requestId;
            emit PDFGenerationQueued(requestId, requests[i].requester, requests[i].templateId);
        }

        return requestIds;
    }

    function _computeRequestId(GenerationRequest calldata request) internal pure returns (bytes32) {
        // RequestId includes ALL fields to ensure uniqueness per signed request
        return keccak256(abi.encode(
            request.requester,
            request.documentHash,
            request.timestamp,
            request.nonce,
            keccak256(bytes(request.templateId))
        ));
    }

    function _hashRequest(GenerationRequest calldata request) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                REQUEST_TYPEHASH,
                request.requester,
                request.documentHash,
                request.timestamp,
                request.nonce,
                keccak256(bytes(request.templateId))
            )
        );
    }

    function _toTypedDataHash(bytes32 structHash) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
    }

    function _validateAndConsumeNonce(address requester, uint256 nonce) internal {
        if (_consumedNonces[requester][nonce]) revert NonceAlreadyUsed();
        _consumedNonces[requester][nonce] = true;
    }

    function isNonceConsumed(address requester, uint256 nonce) external view returns (bool) {
        return _consumedNonces[requester][nonce];
    }
}
